// 1. Captura os dados brutos do pedido
let dadosPedido = $('Edit Fields').first().json || {};

// 2. Captura a saida do Code_Calculadora
let dadosCalculo = $('Code_Calculadora').first().json || {};

// 3. Captura a saida da Stella (Mensagem)
let mensagemStella = $input.first().json.output || $input.first().json.text || "";

// 4. Limpeza da Mensagem
if (/sil.ncio/i.test(mensagemStella)) { mensagemStella = ""; }
mensagemStella = mensagemStella.replace(/```/g, '').trim();

// 5. Formatacao de moeda
function formatarMoeda(valor) {
  if (valor === undefined || valor === null || valor === "") return "0,00";
  let txt = String(valor).replace(/[^\d.,]/g, '');
  if (txt.includes(',') && txt.includes('.')) {
    txt = txt.replace(/\./g, '').replace(',', '.');
  } else if (txt.includes('.') && txt.split('.').pop().length <= 3) {}
  else { txt = txt.replace(',', '.'); }
  let num = Number(txt);
  return isNaN(num) ? "0,00" : num.toFixed(2).replace('.', ',');
}

// 6. Mapeamento - DADOS ORIGINAIS
const whatsFinal = (String(dadosPedido?.Whats).toLowerCase() === 'true') ? true : null;
const responsavelNome = dadosPedido?.Responsavel || "Atendente";
const clienteNome     = dadosPedido?.Cliente || "Cliente";
const largura         = dadosPedido?.Larg || "";
const altura          = dadosPedido?.Alt  || "";
const tecidoOriginal  = dadosPedido?.Tecido || "";
const quantidade      = dadosPedido?.Qtd || 1;
const corFerragem     = dadosPedido?.["Cor Ferragem /Motor"] || dadosPedido?.["Cor Ferragem"] || "";
const acabamentos     = dadosPedido?.Acabamentos || "";
const modeloPersiana  = dadosPedido?.["Modelo de Persiana"] || "Rolo_Motorizado";

// 7. Mapeamento - DADOS CALCULADOS (Rolo Motorizado)
const nomenclaturaComercial = dadosCalculo?.nomenclatura_comercial || tecidoOriginal;
const resumoCalculo         = dadosCalculo?.resumo_agente_calculo || "";
const erroCalculo           = dadosCalculo?.erro || false;
const custoOrcamento        = dadosCalculo?.custos?.rolo_motorizado_total || 0;
const custoM2               = dadosCalculo?.custos?.custo_por_m2 || 0;
const custoAcabamento       = dadosCalculo?.custos?.acabamento_total || 0;
const valorVenda            = dadosCalculo?.vendas?.rolo_motorizado_4x || 0;
const valorInstalacao       = dadosCalculo?.vendas?.instalacao || 0;

// 8. Saida Consolidada
return [{
  json: {
    whats:                         whatsFinal,
    nome_do_responsavel:           responsavelNome,
    nome_do_cliente:               clienteNome,
    modelo_persiana:               modeloPersiana,
    tecido_original:               tecidoOriginal,
    largura:                       largura,
    altura:                        altura,
    quantidade:                    quantidade,
    cor_ferragem:                  corFerragem,
    acabamentos:                   acabamentos,
    custo:                         formatarMoeda(custoOrcamento),
    custo_m2:                      formatarMoeda(custoM2),
    custo_acabamento:              formatarMoeda(custoAcabamento),
    valor_venda:                   formatarMoeda(valorVenda),
    valor_instalacao:              formatarMoeda(valorInstalacao),
    nomenclatura_comercial:        nomenclaturaComercial,
    resumo_calculo:                resumoCalculo,
    erro:                          erroCalculo,
    resumo_curto_valor_ao_cliente: mensagemStella,
    ambiente:             dadosPedido?.ambiente || '',
    ambiente_label:       dadosPedido?.ambiente_label || dadosPedido?.ambiente || '',
    ambiente_index:       parseInt(dadosPedido?.ambiente_index) || 0,
    total_ambientes:      parseInt(dadosPedido?.total_ambientes) || 1,
    preco_instalacao_total:    dadosPedido?.preco_instalacao_total ?? null,
