// Branch SEM WhatsApp: retorna custos ao Supervisor para salvar no Supabase

// 1. Dados do pedido
const pedido = $('Edit Fields').first().json;

// 2. Output do Agent1 — parse do JSON de custos
let rawOutput = $input.first().json.output || $input.first().json.text || '{}';
rawOutput = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
let jsonData = {};
try {
  const match = rawOutput.match(/\{[\s\S]*\}/);
  jsonData = match ? JSON.parse(match[0]) : {};
} catch(e) {}

const resumo = jsonData.custos?.resumo_custos || {};

// 3. Campo de custo principal varia por modelo (custo_rolo_total, custo_double_total, etc.)
const custoBase      = (Number(resumo.custo_rolo_base_total) || 0) + (Number(resumo.custo_motorizacao_total) || 0);
const custoM2        = Number(resumo.custo_por_m2)            || 0;
const custoAcab      = Number(resumo.custo_acabamento_total)   || 0;
const instalacao     = Number(resumo.instalacao_total)         || 0;

function fmt(v) {
  return Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const corFerragem = pedido['Cor Ferragem'] || pedido['Cor Ferragem /Motor'] || '';

return [{
  json: {
    nome_do_responsavel:           pedido.Responsavel             || null,
    nome_do_cliente:               pedido.Cliente                  || null,
    largura:                       String(pedido.Larg || ''),
    altura:                        String(pedido.Alt  || ''),
    modelo_persiana:               pedido['Modelo de Persiana']    || null,
    tecido_original:               pedido.Tecido                   || null,
    quantidade:                    pedido.Qtd                      || 1,
    cor_ferragem:                  corFerragem,
    acabamentos:                   pedido.Acabamentos              || '',
    ambiente:                      pedido.ambiente                 || null,
    ambiente_label:                pedido.ambiente_label           || pedido.ambiente || null,
    custo:                         fmt(custoBase),
    custo_m2:                      fmt(custoM2),
    custo_acabamento:              fmt(custoAcab),
    valor_instalacao:              fmt(instalacao),
    valor_venda:                   null,
    whats:                         false,
    resumo_curto_valor_ao_cliente: '',
    total_ambientes:               pedido.total_ambientes          || 1,
    ambiente_index:                pedido.ambiente_index           || 0,
    _tipo:                         'custo_interno',
    preco_instalacao_total: pedido.preco_instalacao_total ?? null,
    instalacao_sob_consulta: pedido.instalacao_sob_consulta ?? false,
    persiana_grupo: pedido.persiana_grupo || null,
  }
}];

// Prepara dados de custo interno para salvar no Supabase (custos_internos).
// Converte strings BRL → números e mapeia campos.
const item = $input.first().json;

function parseBR(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number') return value;
  const r = parseFloat(String(value).replace(/\./g, '').replace(',', '.'));
  return isNaN(r) ? null : r;
}

return [{
  json: {
    responsavel:        item.nome_do_responsavel  || null,
    cliente:            item.nome_do_cliente       || null,
    modelo:             item.modelo_persiana       || null,
    tecido:             item.tecido_original       || null,
    largura:            parseFloat(item.largura)   || null,
    altura:             parseFloat(item.altura)    || null,
    quantidade:         parseInt(item.quantidade)  || 1,
    cor_ferragem_motor: item.cor_ferragem          || null,
    acabamentos:        item.acabamentos           || null,
    custo_material:     parseBR(item.custo),
    custo_m2:           parseBR(item.custo_m2),
    custo_acabamento:   parseBR(item.custo_acabamento),
    custo_instalacao:   item.preco_instalacao_total != null
                          ? item.preco_instalacao_total
                          : parseBR(item.valor_instalacao),
    ambiente:           item.ambiente              || null,
    fonte:              'supervisor-custo-interno',
    // Marcador para o Supervisor ignorar este item em orcamentos
    _tipo:              'custo_interno',
  }
}];

// Code_Validar_Output v4 — strips markdown fences, string fallback, tool-call text detection
let rawOutput = $input.first().json.output || $input.first().json.text || '';

// 1. Remove markdown fences before parsing
const cleaned = rawOutput
  .replace(/^```(?:json)?s*/i, '')
  .replace(/s*```s*$/, '')
  .trim();

// 2. Parse: try cleaned first, then greedy regex
let jsonData = {};
try {
  jsonData = JSON.parse(cleaned);
} catch(e1) {
  try {
    const m = cleaned.match(/{[sS]*}/);
    if (m) jsonData = JSON.parse(m[0]);
  } catch(e2) {
    jsonData = {};
  }
}

// 3. Structural validation
// Detecta tool call Anthropic ({"type":"tool_use"}) E texto de tool call do Gemini ("Calling X with input:")
const isToolCallJson = !!(jsonData.type && jsonData.type === 'tool_use');
const isToolCallText = /^callings+w/i.test(cleaned) || /callings+(calculator|google|tool|buscar|planilha)/i.test(rawOutput);
const isToolCall = isToolCallJson || isToolCallText;

const temResponsavel = !!(jsonData.responsavel && jsonData.responsavel !== null && jsonData.responsavel !== '');
const temCustos = !!(jsonData.custos && typeof jsonData.custos === 'object');
const temCampoAlternativo = !!(
  jsonData.custo_total !== undefined ||
  jsonData.valor_venda !== undefined ||
  jsonData.custo_rolo_total !== undefined ||
  jsonData.resumo_calculo !== undefined
);

// 4. String fallback (handles edge cases where JSON.parse fails in sandbox)
const strTemResponsavel = rawOutput.includes('"responsavel"') &&
  !rawOutput.includes('"responsavel": null') &&
  !rawOutput.includes('"responsavel":null');
const strTemCustos = rawOutput.includes('"custos"') && (
  rawOutput.includes('custo_rolo_total') ||
  rawOutput.includes('custo_double_total') ||
  rawOutput.includes('custo_romana_total') ||
  rawOutput.includes('custo_vertical_total') ||
  rawOutput.includes('custo_horizontal_total') ||
  rawOutput.includes('custo_painel_total') ||
  rawOutput.includes('custo_cortina_total') ||
  rawOutput.includes('custo_motorizado_total') ||
  rawOutput.includes('instalacao_total') ||
  rawOutput.includes('custo_total')
);

const isValido = (
  ((temResponsavel && (temCustos || temCampoAlternativo)) || (strTemResponsavel && strTemCustos))
  && !isToolCall
);

const dadosPedido = $('Edit Fields').first().json;

if (isValido) {
  return [{ json: { ...$input.first().json, _valido: true, Whats: $('Edit Fields').first().json.Whats } }];
} else {
  const retryCount = (dadosPedido._retry_count || 0) + 1;
  return [{
    json: {
      ...dadosPedido,
      _valido: false,
      Whats: $('Edit Fields').first().json.Whats,
      _output_invalido: rawOutput.slice(0, 400),
      _retry_count: retryCount,
      _parse_attempt: JSON.stringify({ temResponsavel, temCustos, temCampoAlternativo, strTemResponsavel, strTemCustos, isToolCall, isToolCallText }),
    }
  }];
}

// Code_Erro_Definitivo
// Emite marcador de erro quando todas as tentativas falharam
const item = $input.first().json;

const modelo = item['Modelo de Persiana'] || item.modelo || item.tipo_persiana || 'desconhecido';
const cliente = item.Cliente || item.nome_cliente || item.responsavel || 'desconhecido';
const responsavel = item.Resp || item.responsavel || 'equipe';

return [{
  json: {
    erro: true,
    _erro_silencioso: true,
    modelo: modelo,
    cliente: cliente,
    responsavel: responsavel,
    tentativas: 3,
    raw_output: item._output_invalido || '',
    mensagem: `Agente falhou após 3 tentativas — output inválido para ${modelo} do cliente ${cliente}`,
    nome_do_responsavel: responsavel,
    nome_do_cliente: cliente,
    custo: '0,00',
    custo_m2: '0,00',
    custo_acabamento: '0,00',
    valor_venda: '0,00',
    valor_instalacao: '0,00',
    resumo_curto_valor_ao_cliente: '',
    persiana_grupo: item.persiana_grupo || null,
    ambiente: item.ambiente || '',
    ambiente_index: item.ambiente_index || 0,
    total_ambientes: item.total_ambientes || 1,
    whats: false,
    _tipo: 'erro_silencioso',
  }
}];

// 1. Captura os dados brutos do pedido
let dadosPedido = $('Edit Fields').first().json || {};

// 2. Captura a saida do Code_Calculadora
let dadosCalculo = $('Code_Calculadora').first().json || {};

// 3. Captura a saida da Stella (Mensagem)
let mensagemStella = $input.first().json.output || $input.first().json.text || "";

// 4. Limpeza da Mensagem
if (/sil.ncio/i.test(mensagemStella)) { mensagemStella = ""; }
mensagemStella = mensagemStella.replace(/```/g, '').trim();

// 5. Formatacao de moeda
function formatarMoeda(valor) {
  if (valor === undefined || valor === null || valor === "") return "0,00";
  let txt = String(valor).replace(/[^\d.,]/g, '');
  if (txt.includes(',') && txt.includes('.')) {
    txt = txt.replace(/\./g, '').replace(',', '.');
  } else if (txt.includes('.') && txt.split('.').pop().length <= 3) {}
  else { txt = txt.replace(',', '.'); }
  let num = Number(txt);
  return isNaN(num) ? "0,00" : num.toFixed(2).replace('.', ',');
}

// 6. Mapeamento - DADOS ORIGINAIS
const whatsFinal = (String(dadosPedido?.Whats).toLowerCase() === 'true') ? true : null;
const responsavelNome = dadosPedido?.Responsavel || "Atendente";
const clienteNome     = dadosPedido?.Cliente || "Cliente";
const largura         = dadosPedido?.Larg || "";
const altura          = dadosPedido?.Alt  || "";
const tecidoOriginal  = dadosPedido?.Tecido || "";
const quantidade      = dadosPedido?.Qtd || 1;
const corFerragem     = dadosPedido?.["Cor Ferragem /Motor"] || dadosPedido?.["Cor Ferragem"] || "";
const acabamentos     = dadosPedido?.Acabamentos || "";
const modeloPersiana  = dadosPedido?.["Modelo de Persiana"] || "Rolo_Motorizado";

// 7. Mapeamento - DADOS CALCULADOS (Rolo Motorizado)
const nomenclaturaComercial = dadosCalculo?.nomenclatura_comercial || tecidoOriginal;
const resumoCalculo         = dadosCalculo?.resumo_agente_calculo || "";
const erroCalculo           = dadosCalculo?.erro || false;
const custoOrcamento        = dadosCalculo?.custos?.rolo_motorizado_total || 0;
const custoM2               = dadosCalculo?.custos?.custo_por_m2 || 0;
const custoAcabamento       = dadosCalculo?.custos?.acabamento_total || 0;
const valorVenda            = dadosCalculo?.vendas?.rolo_motorizado_4x || 0;
const valorInstalacao       = dadosCalculo?.vendas?.instalacao || 0;

// 8. Saida Consolidada
return [{
  json: {
    whats:                         whatsFinal,
    nome_do_responsavel:           responsavelNome,
    nome_do_cliente:               clienteNome,
    modelo_persiana:               modeloPersiana,
    tecido_original:               tecidoOriginal,
    largura:                       largura,
    altura:                        altura,
    quantidade:                    quantidade,
    cor_ferragem:                  corFerragem,
    acabamentos:                   acabamentos,
    custo:                         formatarMoeda(custoOrcamento),
    custo_m2:                      formatarMoeda(custoM2),
    custo_acabamento:              formatarMoeda(custoAcabamento),
    valor_venda:                   formatarMoeda(valorVenda),
    valor_instalacao:              formatarMoeda(valorInstalacao),
    nomenclatura_comercial:        nomenclaturaComercial,
    resumo_calculo:                resumoCalculo,
    erro:                          erroCalculo,
    resumo_curto_valor_ao_cliente: mensagemStella,
    ambiente:             dadosPedido?.ambiente || '',
    ambiente_label:       dadosPedido?.ambiente_label || dadosPedido?.ambiente || '',
    ambiente_index:       parseInt(dadosPedido?.ambiente_index) || 0,
    total_ambientes:      parseInt(dadosPedido?.total_ambientes) || 1,
    preco_instalacao_total:    dadosPedido?.preco_instalacao_total ?? null,
