    jsonData = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(inputData);
  }
} catch (e) {
  return [{ json: { erro: true, mensagem: "Falha ao ler JSON do Agente." } }];
}

if (jsonData.erro) return [{ json: jsonData }];

const qtd = Number(jsonData.quantidade) || 1;
const resumoExecucao = jsonData.resumo_execucao || "Sem resumo gerado.";
const modeloComercial = jsonData.nomenclatura_comercial || "Rolo Motorizado";

// Extrai Custos da IA
const custoPersianaBase = Number(jsonData.custos?.resumo_custos?.custo_rolo_base_total) || 0;
const custoMotorizacao  = Number(jsonData.custos?.resumo_custos?.custo_motorizacao_total) || 0;
const custoAcabamento   = Number(jsonData.custos?.resumo_custos?.custo_acabamento_total) || 0;
const instalacaoTotal = Number(jsonData.custos?.resumo_custos?.instalacao_total)
  || Number($('Edit Fields').first().json.preco_instalacao_total)
  || 0;

// CINTO DE SEGURANCA: custos zerados = agente nao retornou dados validos
if (custoPersianaBase === 0 && custoMotorizacao === 0) {
  return [{ json: { erro: true, mensagem: "Custos zerados - verifique dados na planilha." } }];
}

const custoPersianaTotal = custoPersianaBase + custoMotorizacao;
// Le do Edit Fields (fonte confiavel) - o agente pode retornar numero de telefone no campo whats
const whatsBool = (String($('Edit Fields').first().json.Whats).toLowerCase() === 'true');

// Matematica de VENDA
function arredondarVenda(valor) { return Math.ceil(valor * 10) / 10; }

let vendaPersianaBase4x = 0;
let vendaMotorizacao4x  = 0;
let vendaAcabamento4x   = 0;

if (whatsBool) {
  vendaPersianaBase4x = arredondarVenda(custoPersianaBase * 2.8 * 1.06 * 1.06);
  vendaMotorizacao4x  = arredondarVenda(custoMotorizacao * 2.24);
  vendaAcabamento4x   = arredondarVenda(custoAcabamento * 2.2 * 1.06 * 1.06);
}

const vendaTotalPersianaEmbutida = vendaPersianaBase4x + vendaMotorizacao4x;
const valorTotalVendaProjeto = vendaTotalPersianaEmbutida + vendaAcabamento4x;

function formatarBRL(valor) {
  if (isNaN(valor)) return "R$ 0,00";
  return "R$ " + valor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

return [{
  json: {
    responsavel: jsonData.responsavel,
    linha: jsonData.linha,
    cliente: jsonData.cliente,
    whats: whatsBool,
    erro: false,
    nomenclatura_comercial: modeloComercial,
    quantidade: qtd,
    resumo_agente_calculo: resumoExecucao,
    // Padrao unificado com os outros 6 sub-workflows
    custos: {
      rolo_motorizado_total: formatarBRL(custoPersianaTotal),
      acabamento_total:      formatarBRL(custoAcabamento),
      custo_por_m2:          formatarBRL(Number(jsonData.custos?.resumo_custos?.custo_por_m2) || 0),
      instalacao:            formatarBRL(instalacaoTotal)
    },
    vendas: {
      rolo_motorizado_4x: formatarBRL(vendaTotalPersianaEmbutida),
      acabamento_4x:      formatarBRL(vendaAcabamento4x),
      instalacao:         formatarBRL(instalacaoTotal)
    },
    // Mantido para compatibilidade com Stella (Basic LLM Chain)
    valores_para_cliente: {
      valor_total_persianas: formatarBRL(vendaTotalPersianaEmbutida),
      valor_acabamentos:     formatarBRL(vendaAcabamento4x),
      valor_total_projeto:   formatarBRL(valorTotalVendaProjeto),
      valor_instalacao:      formatarBRL(instalacaoTotal)
    }
  }
}];

